// Values come from Arduino: button,pot,LED,R,G,B.
let values = [0, 0, 0, 0, 0, 0],
  received = false;
function setup() {
  createCanvas(520, 470);
}
function draw() {
  arduinoComms.poll();
  const [button, pot, led, r, g, b] = values;
  const ink = "#343436";
  const muted = "#77777c";
  background("#fafafa");
  textFont("sans-serif");
  textAlign(LEFT);
  noStroke();
  fill(ink);
  textSize(22);
  text("Four kinds of signal", 24, 36);
  fill(muted);
  textSize(12);
  text(received ? "Live from Arduino" : "Waiting for Arduino…", 24, 60);
  card(24, 82, "DIGITAL INPUT · D2", button ? "Pressed · LOW" : "Released · HIGH");
  fill(button ? "#7b9f87" : muted);
  circle(220, 138, 28);
  card(272, 82, "DIGITAL OUTPUT · D12", led ? "LED on · HIGH" : "LED off · LOW");
  fill(led ? "#ef6c68" : muted);
  circle(468, 138, 28);
  card(24, 194, "ANALOG INPUT · A0", pot + " / 1023");
  fill("#dedee0");
  rect(40, 273, 190, 5, 2);
  fill("#b6a061");
  rect(40, 273, (190 * pot) / 1023, 5, 2);
  card(272, 194, "PWM OUTPUT · D9 / D10 / D11", "RGB color fade");
  fill(r, g, b);
  circle(448, 265, 56);
  textSize(12);
  [
    ["R", r, "#cf6868"],
    ["G", g, "#7b9f87"],
    ["B", b, "#658eac"],
  ].forEach(([label, value, color], i) => {
    const y = 335 + i * 30;
    fill(ink);
    text(label + "  " + value + " / 255", 24, y);
    fill("#dedee0");
    rect(150, y - 9, 340, 7, 2);
    fill(color);
    rect(150, y - 9, (340 * value) / 255, 7, 2);
  });
  fill(muted);
  text("Press the button. Turn the pot to fade the RGB brightness.", 24, 446);
}
function card(x, y, title, value) {
  fill("#eeeeef");
  rect(x, y, 224, 110, 6);
  fill("#77777c");
  textSize(10);
  text(title, x + 16, y + 26);
  fill("#343436");
  textSize(17);
  text(value, x + 16, y + 58);
}

function acceptLine(serialLine) {
  const fields = serialLine.trim().split(",").map(Number);
  if (fields.length === 6 && fields.every(Number.isFinite)) {
    values = fields;
    received = true;
  }
}

