// Four signal types: button in, LED out, potentiometer in, RGB PWM out.
// The button uses INPUT_PULLUP: pressed reads LOW. RGB is common cathode.
const int BUTTON = 2, LED = 12, POT = A0;
const int RED = 9, GREEN = 10, BLUE = 11;
unsigned long lastReport = 0;
void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  pinMode(RED, OUTPUT);
  pinMode(GREEN, OUTPUT);
  pinMode(BLUE, OUTPUT);
  Serial.begin(9600);
}
void loop() {
  bool pressed = digitalRead(BUTTON) == LOW;
  int pot = analogRead(POT);
  digitalWrite(LED, pressed);
  // Crossfade red -> green -> blue. The pot controls brightness.
  int phase = (millis() / 8) % 768;
  int segment = phase / 256, fade = phase % 256;
  int r = segment == 0 ? 255 - fade : segment == 2 ? fade : 0;
  int g = segment == 0 ? fade : segment == 1 ? 255 - fade : 0;
  int b = segment == 1 ? fade : segment == 2 ? 255 - fade : 0;
  r = (long)r * pot / 1023;
  g = (long)g * pot / 1023;
  b = (long)b * pot / 1023;
  analogWrite(RED, r);
  analogWrite(GREEN, g);
  analogWrite(BLUE, b);
  if (millis() - lastReport >= 50) {
    lastReport = millis();
    // CSV: pressed, pot, digital LED, red PWM, green PWM, blue PWM
    Serial.print(pressed); Serial.print(',');
    Serial.print(pot); Serial.print(',');
    Serial.print(pressed); Serial.print(',');
    Serial.print(r); Serial.print(',');
    Serial.print(g); Serial.print(','); Serial.println(b);
  }
  delay(10);
}

